package main

import "strings"

func init() {
	for _, row := range strings.Split(strings.TrimSpace(offMachineCatalog), "\n") {
		cells := strings.Split(row, "|")
		if len(cells) != 8 {
			panic("off-machine translation columns")
		}
		for i, lang := range languages {
			messages[lang]["off_machine_"+cells[0]] = cells[i+1]
		}
	}
}

